const principal = view(Inputs.range([10000, 2000000], {value: 300000, step: 5000, label: "Loan (CHF)"}))
const rate = view(Inputs.range([0, 10], {value: 1.8, step: 0.05, label: "Annual rate (%)"}))
const years = view(Inputs.range([1, 40], {value: 25, step: 1, label: "Years"}))

const calc = (() => {
  const r = rate / 100 / 12, n = years * 12;
  const payment = r === 0 ? principal / n : principal * r / (1 - Math.pow(1 + r, -n));
  return {r, n, payment, total: payment * n, interest: payment * n - principal};
})()

